(7647450, 1243411, 114285, '<td valign="top">Looks like an Irene creation, this is great and sharp!</td>', 'Looks like an Irene creation, this is great and sharp!', '2019-11-29 01:52:19.000000', NULL, 1),
(7647459, 1243405, 59029, '<td valign="top">naptha?</td>', 'naptha?', '2019-11-29 09:46:16.000000', NULL, 1),
(7647460, 1243412, 30049, '<td valign="top">Doesn''t look like your typical panhandler.  Has a jacket, hat, scarf, gloves, blanket, umbrella(I think to the left).  And, all of the garments are in good conditions, no holes, clean, etc...  I''m not saying she isn''t destitute and in need of help, just that she seems unusually tidy for a "street" person.  Framing of the subject, eliminating your reflection, choice of B&amp;W tones, are all well done.  Good luck.</td>', 'Doesn''t look like your typical panhandler.  Has a jacket, hat, scarf, gloves, blanket, umbrella(I think to the left).  And, all of the garments are in good conditions, no holes, clean, etc...  I''m not saying she isn''t destitute and in need of help, just that she seems unusually tidy for a "street" person.  Framing of the subject, eliminating your reflection, choice of B&W tones, are all well done.  Good luck.', '2019-11-29 10:26:00.000000', NULL, 1),
(7647461, 1243421, 30049, '<td valign="top">Oh.  The thumbnail on this looked great, but seeing at larger view that the image isn''t well focused (which is a bummer ... really liked the concept).</td>', 'Oh.  The thumbnail on this looked great, but seeing at larger view that the image isn''t well focused (which is a bummer ... really liked the concept).', '2019-11-29 10:31:21.000000', NULL, 1),
